CREATE TABLE IF NOT EXISTS schema_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE admins (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text UNIQUE NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE admin_sessions (token_hash text PRIMARY KEY, admin_id uuid NOT NULL REFERENCES admins(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE writing_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, description text NOT NULL DEFAULT '', start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, max_pages int NOT NULL CHECK(max_pages BETWEEN 1 AND 30), status text NOT NULL CHECK(status IN ('scheduled','open','closed')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(end_at>start_at));
CREATE TABLE session_themes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES writing_sessions(id) ON DELETE CASCADE, title text NOT NULL, description text NOT NULL DEFAULT '', instructions text NOT NULL DEFAULT '', available boolean NOT NULL DEFAULT true, display_order int NOT NULL CHECK(display_order BETWEEN 0 AND 2), UNIQUE(session_id,display_order));
CREATE TABLE writers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, nim text NOT NULL, email text NOT NULL, membership_status text NOT NULL CHECK(membership_status IN ('anggota','pengurus','non-anggota')), department text, created_at timestamptz NOT NULL DEFAULT now(), CHECK((membership_status='pengurus' AND department IN ('BPH','Technical','Social')) OR (membership_status<>'pengurus' AND department IS NULL)));
CREATE TABLE submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session_id uuid NOT NULL REFERENCES writing_sessions(id) ON DELETE RESTRICT, theme_id uuid NOT NULL REFERENCES session_themes(id) ON DELETE RESTRICT, writer_id uuid NOT NULL REFERENCES writers(id) ON DELETE RESTRICT, owner_hash text NOT NULL, title text NOT NULL DEFAULT 'Tulisan tanpa judul', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','submitted','revision','reviewed')), is_starred boolean NOT NULL DEFAULT false, content_version int NOT NULL DEFAULT 1, submitted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_hash,session_id));
CREATE TABLE submission_pages (id uuid PRIMARY KEY, submission_id uuid NOT NULL REFERENCES submissions(id) ON DELETE CASCADE, page_number int NOT NULL CHECK(page_number>0), title text NOT NULL, content_json jsonb NOT NULL DEFAULT '[]', UNIQUE(submission_id,page_number) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE submission_references (id uuid PRIMARY KEY, submission_id uuid NOT NULL REFERENCES submissions(id) ON DELETE CASCADE, title text NOT NULL, url text NOT NULL, publisher text NOT NULL DEFAULT '', accessed_at date);
CREATE TABLE uploaded_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_id uuid NOT NULL REFERENCES submissions(id) ON DELETE CASCADE, public_url text NOT NULL, storage_key text UNIQUE NOT NULL, mime_type text NOT NULL, file_size int NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ai_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_id uuid NOT NULL REFERENCES submissions(id) ON DELETE CASCADE, content_version int NOT NULL, status text NOT NULL, summary text NOT NULL, findings_json jsonb NOT NULL, sources_json jsonb NOT NULL, search_html text, model_name text NOT NULL, checked_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE admin_notes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_id uuid NOT NULL REFERENCES submissions(id) ON DELETE CASCADE, admin_id uuid REFERENCES admins(id) ON DELETE SET NULL, page_id uuid, note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE submission_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), submission_id uuid NOT NULL REFERENCES submissions(id) ON DELETE CASCADE, content_version int NOT NULL, snapshot jsonb NOT NULL, actor text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, admin_id uuid REFERENCES admins(id) ON DELETE SET NULL, action text NOT NULL, target_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rate_limits (key text PRIMARY KEY, count int NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE settings (key text PRIMARY KEY, value text NOT NULL);
INSERT INTO settings VALUES ('nim_pattern','^[0-9]{5,20}$');
CREATE INDEX submissions_session ON submissions(session_id,status);
CREATE INDEX submissions_starred ON submissions(is_starred) WHERE is_starred;
CREATE INDEX submissions_updated ON submissions(updated_at DESC);
CREATE INDEX reviews_submission ON ai_reviews(submission_id,checked_at DESC);
CREATE INDEX sessions_dates ON writing_sessions(start_at,end_at);
CREATE INDEX notes_submission ON admin_notes(submission_id);
CREATE INDEX revisions_submission ON submission_revisions(submission_id,content_version);
CREATE INDEX admin_sessions_expiry ON admin_sessions(expires_at);
CREATE INDEX rate_expiry ON rate_limits(expires_at);
CREATE TABLE asset_deletion_jobs (storage_key text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
